// Verifica se é 06:00 horário de Brasília
const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
const hour = now.getHours();
if (hour !== 6) return []; // Só executa às 6h

const base = String($env.CK_BASE_URL || 'https://www.conectaking.com.br').replace(/\/$/, '');
const token = String($env.CK_AGENT_JWT || '').trim();
const openaiKey = String($env.OPENAI_API_KEY || '').trim();
const model = String($env.OPENAI_MODEL || 'gpt-4o-mini').trim();
const botToken = String($env.BIBLIA_BOT_TOKEN || '8669321947:AAEm1Ek1gI_wTUDYHNsyyuqbRkPFqLE-NSo').trim();
const chatGroupId = String($env.BIBLIA_GROUP_CHAT_ID || '').trim();

if (!chatGroupId) return [{ json: { skip: true, motivo: 'BIBLIA_GROUP_CHAT_ID não configurado' } }];

// Dia do ano e mês
const start = new Date(now.getFullYear(), 0, 0);
const diff = now - start + ((start.getTimezoneOffset() - now.getTimezoneOffset()) * 60 * 1000);
const doy = Math.min(365, Math.max(1, Math.floor(diff / (1000 * 60 * 60 * 24))));
const month = now.getMonth() + 1;
const year = now.getFullYear();
const iso = now.toISOString().slice(0, 10);

async function ck(method, path, body) {
  const opts = {
    method,
    url: base + path,
    headers: { 'Accept': 'application/json', 'Content-Type': 'application/json',
      ...(token ? { 'Authorization': 'Bearer ' + token } : {}) },
    json: true, returnFullResponse: true, ignoreHttpStatusErrors: true
  };
  if (body !== undefined) opts.body = body;
  return this.helpers.httpRequest.call(this, opts);
}

async function openaiCall(payload) {
  return this.helpers.httpRequest.call(this, {
    method: 'POST', url: 'https://api.openai.com/v1/chat/completions',
    headers: { 'Authorization': 'Bearer ' + openaiKey, 'Accept': 'application/json', 'Content-Type': 'application/json' },
    body: payload, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true
  });
}

async function sendTelegram(text) {
  return this.helpers.httpRequest.call(this, {
    method: 'POST',
    url: `https://api.telegram.org/bot${botToken}/sendMessage`,
    headers: { 'Content-Type': 'application/json' },
    body: { chat_id: chatGroupId, text, parse_mode: 'Markdown' },
    json: true, returnFullResponse: true, ignoreHttpStatusErrors: true
  });
}

// Buscar tema do mês
const temaRes = await ck.call(this, 'GET', `/api/admin/bible/devotionals-365/month-themes/${year}`);
const themes = (temaRes.body && (temaRes.body.data?.themes || temaRes.body.themes)) || {};
const temaDoMes = themes[String(month)] || 'Fé e Confiança em Deus';

// Buscar devocional do dia
const devRes = await ck.call(this, 'GET', `/api/bible/devocional-do-dia?date=${iso}`);
const d = (devRes.body && devRes.body.data) || {};
const temConteudo = !!(d.reflexao || d.texto || d.content);

let texto = '';

if (temConteudo) {
  // Formato padrão — SEM mencionar PNL, Neurociência, Psicologia
  const titulo = d.titulo || d.title || 'Palavra do Dia';
  const passagem = d.versiculo_ref || d.versiculo || d.passagem || d.ref || 'Escrituras Sagradas';
  const vTexto = d.versiculo_texto ? `"${d.versiculo_texto}"\n\n` : '';
  const corpo = d.reflexao || d.texto || d.content || '';
  const oracao = d.oracao || d.prayer || '';
  texto = `✨ *Devocional do Dia:* ${titulo}\n\n📖 *Texto Base:* ${passagem}\n\n${vTexto}${corpo}\n\n${oracao ? '🙏 *Oração:*\n_' + oracao + '_\n\n' : ''}Amém! Que Deus abençoe sua jornada. ❤️`;
} else {
  // Devocional não cadastrado — gerar via backend com tema do mês
  const genRes = await ck.call(this, 'POST', `/api/admin/bible/devotionals-365/day/${doy}/generate-ai`, {
    year, temaPersonalizado: temaDoMes, temaModo: 'mes_auto'
  });
  const gd = (genRes.body && genRes.body.data) || {};
  const titulo = gd.titulo || 'Palavra do Dia';
  const passagem = gd.versiculo_ref || gd.passagem || 'Escrituras Sagradas';
  const vTexto = gd.versiculo_texto ? `"${gd.versiculo_texto}"\n\n` : '';
  const corpo = gd.reflexao || gd.texto || '';
  const oracao = gd.oracao || '';
  texto = `✨ *Devocional do Dia:* ${titulo}\n\n📖 *Texto Base:* ${passagem}\n\n${vTexto}${corpo}\n\n${oracao ? '🙏 *Oração:*\n_' + oracao + '_\n\n' : ''}Amém! Que Deus abençoe sua jornada. ❤️`;
}

await sendTelegram.call(this, texto);
return [{ json: { enviado: true, dia: doy, tema: temaDoMes, data: iso } }];

// Verifica se é 21:00 horário de Brasília
const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
const hour = now.getHours();
if (hour !== 21) return []; // Só executa às 21h

const base = String($env.CK_BASE_URL || 'https://www.conectaking.com.br').replace(/\/$/, '');
const token = String($env.CK_AGENT_JWT || '').trim();
const botToken = String($env.BIBLIA_BOT_TOKEN || '8669321947:AAEm1Ek1gI_wTUDYHNsyyuqbRkPFqLE-NSo').trim();
const chatGroupId = String($env.BIBLIA_GROUP_CHAT_ID || '').trim();

if (!chatGroupId) return [{ json: { skip: true, motivo: 'BIBLIA_GROUP_CHAT_ID não configurado' } }];

// Número da ativação: dia do mês (1-31), cicla por Provérbios
const diaDoMes = now.getDate(); // 1 a 31
const numAtivacao = diaDoMes; // alinha ao capítulo de Provérbios

async function ck(method, path, body) {
  const opts = {
    method, url: base + path,
    headers: { 'Accept': 'application/json', 'Content-Type': 'application/json',
      ...(token ? { 'Authorization': 'Bearer ' + token } : {}) },
    json: true, returnFullResponse: true, ignoreHttpStatusErrors: true
  };
  if (body !== undefined) opts.body = body;
  return this.helpers.httpRequest.call(this, opts);
}

async function sendTelegram(text) {
  return this.helpers.httpRequest.call(this, {
    method: 'POST',
    url: `https://api.telegram.org/bot${botToken}/sendMessage`,
    headers: { 'Content-Type': 'application/json' },
    body: { chat_id: chatGroupId, text, parse_mode: 'Markdown' },
    json: true, returnFullResponse: true, ignoreHttpStatusErrors: true
  });
}

// Buscar ativação de Prosperidade
const r = await ck.call(this, 'GET', `/api/bible/prosperidade/ativacao/${numAtivacao}`);
const p = (r.body && r.body.data) || {};

const titulo = p.titulo || p.title || `Prosperidade Antes de Dormir`;
const ref = p.proverbs_ref || p.versiculo_ref || `Provérbios ${numAtivacao}`;
const meditacao = p.fundamento_sagrado || p.reflexao || p.texto || '';
const declaracao = p.decreto_entrada || p.declaracao || '';

let texto = '';

if (meditacao) {
  texto = `🌙 *31 Dias de Ativação — Prosperidade Antes de Dormir*\n\n💎 *Ativação #${numAtivacao}: ${titulo}*\n\n📖 *${ref}*\n\n${meditacao}\n\n🗣️ *Declare antes de dormir:*\n_"${declaracao}"_\n\n✨ Deus tem prazer na prosperidade integral da sua vida!`;
} else {
  // Ativação não cadastrada — gerar via backend
  const genR = await ck.call(this, 'POST', `/api/admin/bible/prosperidade/${numAtivacao}/generate-ai`);
  const gp = (genR.body && genR.body.data) || {};
  const gTitulo = gp.titulo || `Prosperidade Antes de Dormir`;
  const gRef = gp.proverbs_ref || `Provérbios ${numAtivacao}`;
  const gMed = gp.fundamento_sagrado || gp.reflexao || '';
  const gDecr = gp.decreto_entrada || gp.sentenca_ativacao || '';
  texto = `🌙 *31 Dias de Ativação — Prosperidade Antes de Dormir*\n\n💎 *Ativação #${numAtivacao}: ${gTitulo}*\n\n📖 *${gRef}*\n\n${gMed}\n\n🗣️ *Declare antes de dormir:*\n_"${gDecr}"_\n\n✨ Deus tem prazer na prosperidade integral da sua vida!`;
}

await sendTelegram.call(this, texto);
return [{ json: { enviado: true, ativacao: numAtivacao } }];
